"use client";

import * as React from "react";

import { useToday } from "@/hooks/use-now";
import { useCalendar, useCalendarConfig } from "@/components/calendar-provider";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@/components/ui/dialog";
import { Kbd, KbdGroup } from "@/components/ui/kbd";
import { TimeZoneList } from "@/components/time-zone-list";
import { formatDateQueryResult, parseDateQuery } from "@/lib/date-query";
import { NUMBER_OF_DAYS_OPTIONS } from "@/lib/event-utils";
import {
  addTimeZone,
  getViewerTimeZone,
  makeTimeZonePrimary,
  removeTimeZone,
} from "@/lib/time-zones";
import type { WeekStartsOn } from "@/components/calendar-types";
import type {
  CommandMenuPage,
  TimeZoneCommand,
} from "@/components/week-view-types";

/** Reusable "Soon" badge for unimplemented command items */
const SOON_BADGE = (
  <span className="bg-muted text-muted-foreground ml-auto rounded px-1.5 py-0.5 text-[10px] leading-none font-medium">
    Soon
  </span>
);

/**
 * The menu's look, on the dialog: translucent and blurred in dark mode, and
 * a gap between groups. `data-command-menu` on the same element lets the CSS
 * that ships with the menu dim the page less in dark mode.
 */
const DIALOG_CLASS =
  "overflow-hidden p-0 dark:bg-popover/60 dark:backdrop-blur-xl dark:border-border/50 dark:[&_[data-slot=command]]:bg-transparent [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-2";

/** Taller input and items, and padded group headings, as shadcn/ui's CommandDialog has them */
const COMMAND_CLASS =
  "**:data-[slot=command-input-wrapper]:h-12 [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground [&_[cmdk-group]]:px-2 [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0 [&_[cmdk-input-wrapper]_svg]:h-5 [&_[cmdk-input-wrapper]_svg]:w-5 [&_[cmdk-input]]:h-12 [&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-3 [&_[cmdk-item]_svg]:h-5 [&_[cmdk-item]_svg]:w-5";

/** Go to date's placeholder, as Notion Calendar's */
const GO_TO_DATE_PLACEHOLDER = "e.g. nov 5, in 10 weeks";

/** Each time zone command's label, which its list's input shows too */
const TIME_ZONE_COMMAND_LABELS: Record<TimeZoneCommand, string> = {
  travel: "Travel to time zone...",
  add: "Show additional time zones...",
  primary: "Make time zone primary...",
  hide: "Hide time zone...",
};

/** A list of choices the menu shows in place of the commands, as Notion Calendar's does */
type ChoiceList = "week-start" | "number-of-days";

/** Each list's command label, which its input shows too, as Notion Calendar words it */
const CHOICE_LIST_LABELS: Record<ChoiceList, string> = {
  "week-start": "Start week on...",
  "number-of-days": "Set number of displayed days...",
};

/**
 * Days "Start week on..." offers, Monday first, and how it names them. The
 * day the week starts on now is left out, as in Notion Calendar.
 */
const WEEK_START_CHOICES: Array<{ day: WeekStartsOn; label: string }> = [
  { day: 1, label: "Mondays" },
  { day: 2, label: "Tuesdays" },
  { day: 3, label: "Wednesdays" },
  { day: 4, label: "Thursdays" },
  { day: 5, label: "Fridays" },
  { day: 6, label: "Saturdays" },
  { day: 0, label: "Sundays" },
];

/** One command of the menu */
interface MenuCommand {
  label: string;
  /** Shortcut keys shown on the right, e.g. ["⌘", "/"] */
  keys?: string[];
  /** Runs the command once the menu has closed. Missing when the app doesn't offer it */
  run?: () => void;
  /**
   * The command focuses something (a field, a new event's title): it runs
   * once the menu has closed and given focus back
   */
  movesFocus?: boolean;
  /** Not built yet: listed disabled with a "Soon" badge, only with `showComingSoon` */
  soon?: boolean;
  /**
   * Runs with the menu still open: it shows what to type or pick next in
   * its place (Go to date's field, a zone list, a list of choices)
   */
  keepsOpen?: boolean;
}

/** A titled group of commands */
interface MenuGroup {
  heading: string;
  commands: MenuCommand[];
}

interface CommandMenuProps {
  /** Whether the menu is open */
  open: boolean;
  /** Called when the menu opens or closes, including after a command runs */
  onOpenChange: (open: boolean) => void;
  /** Adds "Toggle sidebar" (⌘ /) */
  onToggleSidebar?: () => void;
  /** Adds "Toggle context panel" (/) */
  onToggleContextPanel?: () => void;
  /** Adds "Set theme..." (Shift M) */
  onCycleTheme?: () => void;
  /** Adds "Import .ics file..." */
  onImportIcs?: () => void;
  /** Adds "Export .ics file" */
  onExportIcs?: () => void;
  /** Adds "Meet with..." (F): open a people picker that meets with who you pick */
  onMeetWith?: () => void;
  /** Adds "Show teammate calendar..." (P): open a people picker that shows their calendar */
  onShowTeammateCalendar?: () => void;
  /**
   * Adds "Search events", and "Search events for “…”" once text is typed:
   * opens your event search with that text (empty for the first)
   */
  onSearchEvents?: (query: string) => void;
  /** Adds "Show keyboard shortcuts" (?) */
  onShowShortcuts?: () => void;
  /**
   * Page the menu opens on, each time it opens: its commands, or Go to
   * date's field (as the . key does). Defaults to "commands"
   */
  defaultPage?: CommandMenuPage;
  /**
   * Also lists the Notion Calendar commands CalendarCN doesn't have yet,
   * disabled with a "Soon" badge, as the live demo does
   */
  showComingSoon?: boolean;
  /**
   * Opens the menu on a time zone command's list instead of the commands,
   * e.g. `"travel"` for the Z key
   */
  timeZoneCommand?: TimeZoneCommand;
}

/**
 * The live demo's ⌘K menu. Creating an event, going to a date, today,
 * previous and next, the views, the view settings, the week start, the day
 * count, the hour size and the time zones come from `useCalendar()`, so it
 * goes inside `CalendarProvider`. A time zone command lists the zones in the
 * menu's place, and "Start week on..." and "Set number of displayed days..."
 * their choices. Commands that belong to your
 * app (panels, search, shortcuts, theme, .ics files) show only when you pass
 * their callback. Open it with `useCalendarShortcuts({ onToggleCommandMenu })`.
 *
 * "Go to date..." turns the field into a date field, as in Notion Calendar:
 * type a date ("tomorrow", "next friday", "dec 25", "in 2 weeks"), see which
 * day it reads, and press Enter to show it in the current view. A time zone
 * command lists the zones in the menu's place. Backspace in the empty field
 * goes back to the commands.
 */
export function CommandMenu({
  open,
  onOpenChange,
  onToggleSidebar,
  onToggleContextPanel,
  onCycleTheme,
  onImportIcs,
  onExportIcs,
  onMeetWith,
  onShowTeammateCalendar,
  onSearchEvents,
  onShowShortcuts,
  defaultPage = "commands",
  showComingSoon = false,
  timeZoneCommand,
}: CommandMenuProps) {
  const {
    goToToday,
    goToPrev,
    goToNext,
    switchView,
    viewSettings,
    toggleWeekends,
    toggleDeclinedEvents,
    toggleWeekNumbers,
    weekStartsOn,
    setWeekStartsOn,
    setNumberOfDays,
    zoomHoursIn,
    zoomHoursOut,
    resetHourHeight,
    navigateToDate,
    addEventAtNextSlot,
    timeZones,
    changeTimeZones,
    travelToTimeZone,
  } = useCalendar();
  /** The page shown: the commands, or Go to date's field */
  const [page, setPage] = React.useState<CommandMenuPage>(defaultPage);
  /** The time zone command whose list shows in place of the commands */
  const [zoneCommand, setZoneCommand] = React.useState<TimeZoneCommand | null>(
    null,
  );
  /** The list of choices shown in place of the commands, if one is */
  const [choiceList, setChoiceList] = React.useState<ChoiceList | null>(null);
  /** Text typed in the input, for the commands, Go to date or a list */
  const [query, setQuery] = React.useState("");
  /** The input, focused again when a zone list or Go to date replaces the commands */
  const inputRef = React.useRef<HTMLInputElement>(null);
  // Each opening starts on `defaultPage`, or on the list `timeZoneCommand`
  // names, with an empty field. Adjusted while rendering, so the first frame
  // is already right
  const [wasOpen, setWasOpen] = React.useState(open);
  if (open !== wasOpen) {
    setWasOpen(open);
    if (open) {
      setPage(defaultPage);
      setZoneCommand(timeZoneCommand ?? null);
      setChoiceList(null);
      setQuery("");
    }
  }
  const hasOtherZones = timeZones.secondary.length > 0;

  const runCommand = React.useCallback(
    (command: () => void) => {
      onOpenChange(false);
      command();
    },
    [onOpenChange],
  );

  /** The dialog's content, while it's in the page */
  const contentRef = React.useRef<HTMLDivElement>(null);

  /**
   * Closes the menu, then runs `command` once the dialog has left the page
   * and handed focus back to where it was, so the focus `command` moves
   * stays
   */
  const runCommandAfterClose = React.useCallback(
    (command: () => void) => {
      onOpenChange(false);
      const runOnceClosed = () => {
        if (contentRef.current?.isConnected) {
          requestAnimationFrame(runOnceClosed);
          return;
        }
        setTimeout(command, 0);
      };
      requestAnimationFrame(runOnceClosed);
    },
    [onOpenChange],
  );

  /** Runs a picked command: in place, then or once the menu has closed */
  const selectCommand = ({ run, keepsOpen, movesFocus }: MenuCommand) => {
    if (!run) return;
    if (keepsOpen) {
      run();
      return;
    }
    if (movesFocus) {
      runCommandAfterClose(run);
      return;
    }
    runCommand(run);
  };

  /** Shows a page of the menu with an empty field */
  const showPage = React.useCallback((next: CommandMenuPage) => {
    setPage(next);
    setQuery("");
  }, []);

  /** Lists a time zone command's zones in place of the commands */
  const openZoneCommand = (command: TimeZoneCommand) => {
    setZoneCommand(command);
    setQuery("");
  };

  /** Lists a command's choices in place of the commands */
  const openChoiceList = (list: ChoiceList) => {
    setChoiceList(list);
    setQuery("");
  };

  // A click on Go to date, a time zone command or a list of choices takes
  // the focus: give it back to the input, so typing goes there
  React.useEffect(() => {
    if (zoneCommand || choiceList || page !== "commands") {
      inputRef.current?.focus();
    }
  }, [zoneCommand, choiceList, page]);

  // Backspace in an empty date, zone or choice field goes back to the commands
  const handleInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key !== "Backspace" || query !== "") return;
    if (!zoneCommand && !choiceList && page === "commands") return;
    e.preventDefault();
    setZoneCommand(null);
    setChoiceList(null);
    showPage("commands");
  };

  /** Runs the open time zone command on the zone picked */
  const pickZone = (zone: string) => {
    if (zoneCommand === "travel") {
      runCommand(() => travelToTimeZone(zone));
      return;
    }
    const change = {
      add: addTimeZone,
      primary: makeTimeZonePrimary,
      hide: removeTimeZone,
    }[zoneCommand ?? "add"];
    runCommand(() => changeTimeZones((zones) => change(zones, zone)));
  };

  /** The zones "Hide time zone..." and "Make time zone primary..." list */
  const listedZones = (() => {
    if (zoneCommand === "primary") return [...timeZones.secondary].reverse();
    if (zoneCommand !== "hide") return undefined;
    // The primary zone first, then the others from the closest
    const primary = timeZones.primary ?? getViewerTimeZone();
    return [primary, ...[...timeZones.secondary].reverse()];
  })();

  const groups: MenuGroup[] = [
    {
      heading: "Calendar",
      commands: [
        {
          label: "Create event...",
          keys: ["C"],
          run: addEventAtNextSlot,
          movesFocus: true,
        },
        { label: "Meet with...", keys: ["F"], run: onMeetWith },
        {
          label: "Show teammate calendar...",
          keys: ["P"],
          run: onShowTeammateCalendar,
        },
        { label: "Create recurring scheduling link...", soon: true },
        { label: "Create one-off scheduling link...", soon: true },
        { label: "Import .ics file...", run: onImportIcs },
        { label: "Export .ics file", run: onExportIcs },
      ],
    },
    {
      heading: "Navigation",
      commands: [
        {
          label: "Go to date...",
          keys: ["."],
          run: () => showPage("go-to-date"),
          keepsOpen: true,
        },
        { label: "Go to today", keys: ["T"], run: goToToday },
        { label: "Go to next week", keys: ["K"], run: goToNext },
        { label: "Go to previous week", keys: ["J"], run: goToPrev },
        {
          label: "Search events",
          run: onSearchEvents ? () => onSearchEvents("") : undefined,
          movesFocus: true,
        },
      ],
    },
    {
      heading: "Time zones",
      commands: [
        {
          label: TIME_ZONE_COMMAND_LABELS.travel,
          keys: ["Z"],
          keepsOpen: true,
          run: () => openZoneCommand("travel"),
        },
        {
          label: TIME_ZONE_COMMAND_LABELS.add,
          keepsOpen: true,
          run: () => openZoneCommand("add"),
        },
        // Only with more than one zone, as in Notion Calendar
        {
          label: TIME_ZONE_COMMAND_LABELS.primary,
          keepsOpen: true,
          run: hasOtherZones ? () => openZoneCommand("primary") : undefined,
        },
        {
          label: TIME_ZONE_COMMAND_LABELS.hide,
          keepsOpen: true,
          run: hasOtherZones ? () => openZoneCommand("hide") : undefined,
        },
      ],
    },
    {
      heading: "App",
      commands: [
        { label: "Toggle sidebar", keys: ["⌘", "/"], run: onToggleSidebar },
        { label: "Set theme...", keys: ["shift", "M"], run: onCycleTheme },
      ],
    },
    {
      heading: "View",
      commands: [
        {
          label: CHOICE_LIST_LABELS["week-start"],
          keepsOpen: true,
          run: () => openChoiceList("week-start"),
        },
        {
          label: "Display day view",
          keys: ["D"],
          run: () => switchView("day"),
        },
        {
          label: "Display week view",
          keys: ["W"],
          run: () => switchView("week"),
        },
        {
          label: "Display month view",
          keys: ["M"],
          run: () => switchView("month"),
        },
        {
          label: "Display year view",
          keys: ["Y"],
          run: () => switchView("year"),
        },
        {
          label: "Display agenda view",
          keys: ["A"],
          run: () => switchView("agenda"),
        },
        {
          label: CHOICE_LIST_LABELS["number-of-days"],
          keepsOpen: true,
          run: () => openChoiceList("number-of-days"),
        },
        { label: "Select all visible", soon: true },
        {
          label: "Default hour size",
          keys: ["shift", "⌘", "0"],
          run: resetHourHeight,
        },
        {
          label: "Zoom hours in",
          keys: ["shift", "⌘", "."],
          run: zoomHoursIn,
        },
        {
          label: "Zoom hours out",
          keys: ["shift", "⌘", ","],
          run: zoomHoursOut,
        },
        // Each says what it will do, as Notion Calendar's do
        {
          label: viewSettings.showWeekends ? "Hide weekends" : "Show weekends",
          keys: ["shift", "⌘", "E"],
          run: toggleWeekends,
        },
        {
          label: viewSettings.showDeclinedEvents
            ? "Hide declined events"
            : "Show declined events",
          run: toggleDeclinedEvents,
        },
        {
          label: viewSettings.showWeekNumbers
            ? "Hide week numbers"
            : "Show week numbers",
          run: toggleWeekNumbers,
        },
      ],
    },
    {
      heading: "Settings & help",
      commands: [
        { label: "Get CalendarCN mobile app", soon: true },
        {
          label: "Show keyboard shortcuts",
          keys: ["?"],
          run: onShowShortcuts,
          movesFocus: true,
        },
        { label: "Go to settings", soon: true },
        { label: "Support & feedback", soon: true },
      ],
    },
    {
      heading: "Accounts",
      commands: [
        { label: "Add Google Calendar account", soon: true },
        { label: "Manage calendar accounts", soon: true },
        { label: "Log out", soon: true },
      ],
    },
    {
      heading: "CalendarCN",
      commands: [
        { label: "Check for update", soon: true },
        { label: "About CalendarCN", soon: true },
      ],
    },
    {
      heading: "Panels",
      commands: [
        {
          label: "Toggle context panel",
          keys: ["/"],
          run: onToggleContextPanel,
        },
      ],
    },
  ];
  // Go to date's page lists the typed date alone, a zone list its zones
  const shownGroups =
    page === "commands" && !zoneCommand && !choiceList ? groups : [];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        ref={contentRef}
        showCloseButton={false}
        data-command-menu=""
        className={DIALOG_CLASS}
      >
        <DialogTitle className="sr-only">Command Menu</DialogTitle>
        <DialogDescription className="sr-only">
          Search for a command to run...
        </DialogDescription>
        {/* Go to date's result and a zone list do their own filtering */}
        <Command
          className={COMMAND_CLASS}
          shouldFilter={zoneCommand === null && page === "commands"}
        >
          <CommandInput
            ref={inputRef}
            placeholder={
              zoneCommand
                ? TIME_ZONE_COMMAND_LABELS[zoneCommand]
                : choiceList
                  ? CHOICE_LIST_LABELS[choiceList]
                  : page === "go-to-date"
                    ? GO_TO_DATE_PLACEHOLDER
                    : "Type a command..."
            }
            value={query}
            onValueChange={setQuery}
            onKeyDown={handleInputKeyDown}
          />
          <CommandList>
            {zoneCommand && (
              <TimeZoneList
                query={query}
                onSelect={pickZone}
                timeZones={listedZones}
              />
            )}
            {!zoneCommand && (page === "commands" || query.trim() !== "") && (
              <CommandEmpty>No results found.</CommandEmpty>
            )}
            {choiceList === "week-start" &&
              WEEK_START_CHOICES.filter(({ day }) => day !== weekStartsOn).map(
                ({ day, label }) => (
                  <CommandItem
                    key={label}
                    onSelect={() => runCommand(() => setWeekStartsOn(day))}
                  >
                    {label}
                  </CommandItem>
                ),
              )}
            {/* Bare numbers, as Notion Calendar lists them */}
            {choiceList === "number-of-days" &&
              NUMBER_OF_DAYS_OPTIONS.map((count) => (
                <CommandItem
                  key={count}
                  value={String(count)}
                  onSelect={() => runCommand(() => setNumberOfDays(count))}
                >
                  {count}
                </CommandItem>
              ))}
            {shownGroups.map((group) => {
              const commands = group.commands.filter((command) =>
                command.soon ? showComingSoon : command.run !== undefined,
              );
              if (commands.length === 0) return null;

              return (
                <CommandGroup key={group.heading} heading={group.heading}>
                  {commands.map((command) => (
                    <CommandItem
                      key={command.label}
                      disabled={command.soon}
                      onSelect={
                        command.run ? () => selectCommand(command) : undefined
                      }
                    >
                      {command.label}
                      {command.soon && SOON_BADGE}
                      {command.keys && (
                        <KbdGroup className="ml-auto">
                          {command.keys.map((key) => (
                            <Kbd key={key}>{key}</Kbd>
                          ))}
                        </KbdGroup>
                      )}
                    </CommandItem>
                  ))}
                </CommandGroup>
              );
            })}
            {shownGroups.length > 0 &&
              onSearchEvents &&
              query.trim() !== "" && (
                <CommandGroup heading="Search" forceMount>
                  <CommandItem
                    forceMount
                    value={`search-events-${query}`}
                    onSelect={() =>
                      runCommandAfterClose(() => onSearchEvents(query.trim()))
                    }
                  >
                    Search events for “{query.trim()}”
                  </CommandItem>
                </CommandGroup>
              )}
            {page === "go-to-date" && !zoneCommand && (
              <GoToDateResult
                query={query}
                onSelect={(date) => runCommand(() => navigateToDate(date))}
              />
            )}
          </CommandList>

          <div className="border-t px-3 py-2 flex items-center gap-4 text-xs text-muted-foreground">
            <span className="flex items-center gap-1">
              <span className="text-muted-foreground/70">↑↓</span> Navigate
            </span>
            <span className="flex items-center gap-1">
              <span className="text-muted-foreground/70">↵</span> Select
            </span>
            <span className="flex items-center gap-1">
              <Kbd>esc</Kbd> Close
            </span>
          </div>
        </Command>
      </DialogContent>
    </Dialog>
  );
}

interface GoToDateResultProps {
  /** Text typed in Go to date's field */
  query: string;
  /** Called with the day the text reads when it's picked */
  onSelect: (date: Date) => void;
}

/**
 * Go to date's one result: the day the typed text reads, with its weekday
 * so "next friday" can be checked before going there. Nothing while the text
 * reads as no date.
 */
function GoToDateResult({ query, onSelect }: GoToDateResultProps) {
  const { weekStartsOn } = useCalendar();
  const { locale, timeZone } = useCalendarConfig();
  const today = useToday(timeZone);
  if (!today) return null;
  const date = parseDateQuery(query, { today, locale, weekStartsOn });
  if (!date) return null;

  return (
    <CommandGroup heading="Go to date">
      <CommandItem value={query} onSelect={() => onSelect(date)}>
        {formatDateQueryResult(date, today, locale)}
      </CommandItem>
    </CommandGroup>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import {
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandSeparator,
} from "@/components/ui/command";
import {
  POPULAR_TIME_ZONES,
  getTimeZoneOption,
  getTimeZoneOptions,
  searchTimeZones,
} from "@/lib/time-zones";
import type {
  TimeZoneListProps,
  TimeZoneListVariant,
  TimeZoneOption,
} from "./week-view-types";

/** En dash between a zone's name and its city, as Notion Calendar writes it */
const NAME_CITY_SEPARATOR = " – ";

/** A titled run of zones in the list */
interface TimeZoneSection {
  key: string;
  /** Heading above the zones; none for the popular ones on top */
  heading?: string;
  options: TimeZoneOption[];
}

/** Classes of each list's items and muted text */
const VARIANT_CLASSES: Record<
  TimeZoneListVariant,
  { item: string; muted: string; heading: string; separator: string }
> = {
  command: {
    item: "",
    muted: "text-muted-foreground",
    heading: "",
    separator: "",
  },
  menu: {
    item: "h-[30px] gap-[9px] rounded-md py-0 pr-2 pl-1.5 text-sm text-[#D4D4D4] data-[selected=true]:bg-[#303030] data-[selected=true]:text-[#D4D4D4]",
    muted: "text-[#7F7F7F]",
    heading: "[&_[cmdk-group-heading]]:text-[#7F7F7F]",
    separator: "mx-0 bg-[#303030]",
  },
};

/**
 * The zones of a time zone picker, for Notion Calendar's "Travel to time
 * zone...", "Show additional time zones..." and the time axis labels'
 * menus. Renders cmdk groups: put it in a `Command` with
 * `shouldFilter={false}` next to the input that sets `query`. Without a
 * query it lists the popular zones, then every zone by offset under "All
 * time zones"; a query lists the zones whose offset, city, name or id
 * match it.
 */
export function TimeZoneList({
  query,
  onSelect,
  timeZones,
  variant = "command",
}: TimeZoneListProps) {
  // Offsets as of when the list opened
  const [now] = React.useState(() => new Date());
  // Every zone, listed once per mount: typing searches it
  const allOptions = React.useMemo(() => getTimeZoneOptions(now), [now]);
  const classes = VARIANT_CLASSES[variant];

  const sections = React.useMemo<TimeZoneSection[]>(() => {
    const byId = new Map(allOptions.map((option) => [option.id, option]));
    const pick = (ids: string[]) =>
      ids.map((id) => byId.get(id) ?? getTimeZoneOption(now, id));
    if (timeZones) {
      return [
        { key: "shown", options: searchTimeZones(pick(timeZones), query) },
      ];
    }
    if (query.trim()) {
      return [{ key: "search", options: searchTimeZones(allOptions, query) }];
    }
    return [
      { key: "popular", options: pick(POPULAR_TIME_ZONES) },
      { key: "all", heading: "All time zones", options: allOptions },
    ];
  }, [allOptions, now, timeZones, query]);

  return (
    <>
      <CommandEmpty className={cn("py-6 text-center text-sm", classes.muted)}>
        No time zones found.
      </CommandEmpty>
      {sections.map((section, index) => (
        <React.Fragment key={section.key}>
          {index > 0 && <CommandSeparator className={classes.separator} />}
          <CommandGroup
            heading={section.heading}
            className={cn(variant === "menu" && "p-1", classes.heading)}
          >
            {section.options.map((option) => (
              <CommandItem
                key={option.id}
                // Unique across sections: a popular zone is also under "All"
                value={`${section.key}:${option.id}`}
                onSelect={() => onSelect(option.id)}
                className={classes.item}
              >
                {variant === "command" ? (
                  <span className="min-w-0 truncate">
                    ({option.offsetLabel}) {option.name}
                    {NAME_CITY_SEPARATOR}
                    {option.city}
                  </span>
                ) : (
                  <>
                    <span className={cn("shrink-0", classes.muted)}>
                      {option.offsetLabel}
                    </span>
                    <span className="min-w-0 flex-1 truncate">
                      {option.name}
                      {NAME_CITY_SEPARATOR}
                      {option.city}
                    </span>
                  </>
                )}
              </CommandItem>
            ))}
          </CommandGroup>
        </React.Fragment>
      ))}
    </>
  );
}

import {
  addDays,
  addMonths,
  addWeeks,
  addYears,
  differenceInCalendarDays,
  differenceInCalendarMonths,
  format,
  startOfDay,
  startOfMonth,
  startOfWeek,
  startOfYear,
} from "date-fns";
import { enUS } from "date-fns/locale";
import type { Locale } from "date-fns";

import type { WeekStartsOn } from "@/components/calendar-types";

/** What a typed date counts from, and how it reads month and day names */
export interface DateQueryOptions {
  /** The day "today", "tomorrow" and "in 2 weeks" count from */
  today: Date;
  /**
   * Locale for month and weekday names and the order of a numeric date
   * ("12/25" in en-US, "25/12" in en-GB). English names always work too.
   * Defaults to en-US
   */
  locale?: Locale;
  /**
   * Day the week starts on, for "next week" and "next friday". Defaults to
   * the locale's first day
   */
  weekStartsOn?: WeekStartsOn;
}

/** A period phrases count in: "in 2 weeks", "next month" */
type QueryUnit = "day" | "week" | "month" | "year";

/** Where a weekday or period phrase points: "last", "this" or "next" */
type QueryDirection = -1 | 0 | 1;

/** Years to look ahead for a date without a year: Feb 29 comes back within four */
const LEAP_YEAR_CYCLE = 4;

/** Fewest letters a typed name needs to match a month or weekday by its start ("sept", "thurs") */
const MIN_NAME_PREFIX = 3;

/** One-word dates, as days from today */
const DAY_WORDS: Record<string, number> = {
  today: 0,
  tod: 0,
  now: 0,
  tomorrow: 1,
  tmr: 1,
  tmrw: 1,
  tom: 1,
  yesterday: -1,
  yday: -1,
};

/** Words for the direction of "next friday", "last week", "this month" */
const DIRECTION_WORDS: Record<string, QueryDirection> = {
  next: 1,
  last: -1,
  previous: -1,
  prev: -1,
  this: 0,
  current: 0,
};

/** Unit words of "in 2 weeks" and "next month", singular and plural */
const UNIT_WORDS: Record<string, QueryUnit> = {
  d: "day",
  day: "day",
  days: "day",
  w: "week",
  wk: "week",
  wks: "week",
  week: "week",
  weeks: "week",
  m: "month",
  mo: "month",
  month: "month",
  months: "month",
  y: "year",
  yr: "year",
  yrs: "year",
  year: "year",
  years: "year",
};

/** Words dropped before reading a date: "the 25th of december", "25 de dezembro" */
const FILLER_WORDS = new Set(["the", "of", "on", "de", "del"]);

/** Adds an amount of a unit to a day */
const ADD_UNIT: Record<QueryUnit, (date: Date, amount: number) => Date> = {
  day: addDays,
  week: addWeeks,
  month: addMonths,
  year: addYears,
};

/** Lowercase, without accents, trailing dots or commas: "Déc." → "dec" */
function normalizeName(name: string): string {
  return name
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\.$/, "");
}

/**
 * Whether a typed word names `names` (a month's or a weekday's names, full
 * name first): one of them exactly, or the start of the full name from
 * MIN_NAME_PREFIX letters ("sept", "thurs")
 */
function matchesName(word: string, names: string[]): boolean {
  if (names.includes(word)) return true;
  return (
    word.length >= MIN_NAME_PREFIX &&
    names.some((name) => name.startsWith(word))
  );
}

/** The locales whose names count: the calendar's first, then English */
function nameLocales(locale: Locale): Locale[] {
  return locale.code === enUS.code ? [locale] : [locale, enUS];
}

/** Month (0-11) a word names, in the locale or English, or -1 */
function readMonth(word: string, locale: Locale): number {
  for (const nameLocale of nameLocales(locale)) {
    for (let month = 0; month < 12; month++) {
      const date = new Date(2000, month, 1);
      const names = ["MMMM", "LLLL", "MMM", "LLL"].map((pattern) =>
        normalizeName(format(date, pattern, { locale: nameLocale })),
      );
      if (matchesName(word, names)) return month;
    }
  }
  return -1;
}

/** Weekday (0 = Sunday) a word names, in the locale or English, or -1 */
function readWeekday(word: string, locale: Locale): number {
  for (const nameLocale of nameLocales(locale)) {
    for (let weekday = 0; weekday < 7; weekday++) {
      // January 2, 2000 was a Sunday
      const date = new Date(2000, 0, 2 + weekday);
      const names = ["EEEE", "cccc", "EEE", "ccc", "EEEEEE"].map((pattern) =>
        normalizeName(format(date, pattern, { locale: nameLocale })),
      );
      if (matchesName(word, names)) return weekday;
    }
  }
  return -1;
}

/** The day `month`/`day` of `year`, or null when it doesn't exist (Feb 30) */
function calendarDay(year: number, month: number, day: number): Date | null {
  if (month < 0 || month > 11 || day < 1 || day > 31) return null;
  const date = new Date(year, month, day);
  if (date.getMonth() !== month || date.getDate() !== day) return null;
  // Years 0-99 would land in 1900-1999
  date.setFullYear(year);
  return date;
}

/** A two-digit year in the 2000s ("27" → 2027), others as written */
function readYear(digits: string): number {
  const year = Number(digits);
  return digits.length <= 2 ? 2000 + year : year;
}

/**
 * The next `month`/`day` from today, today included: "dec 25" typed in
 * November is this year's, "oct 30" next year's, as Notion Calendar reads
 * them. Feb 29 waits for the next leap year.
 */
function nextCalendarDay(month: number, day: number, today: Date): Date | null {
  for (let shift = 0; shift <= LEAP_YEAR_CYCLE; shift++) {
    const candidate = calendarDay(today.getFullYear() + shift, month, day);
    if (candidate && differenceInCalendarDays(candidate, today) >= 0) {
      return candidate;
    }
  }
  return null;
}

/** The next day `day` of a month from today, today included: "3rd" typed on the 17th is next month's */
function nextDayOfMonth(day: number, today: Date): Date | null {
  for (let shift = 0; shift < 12; shift++) {
    const month = addMonths(startOfMonth(today), shift);
    const candidate = calendarDay(month.getFullYear(), month.getMonth(), day);
    if (candidate && differenceInCalendarDays(candidate, today) >= 0) {
      return candidate;
    }
  }
  return null;
}

/**
 * The first day of `month` in the year nearest to today's month: "jan" typed
 * in November means the coming January, "oct" the October just gone
 */
function nearestMonthStart(month: number, today: Date): Date {
  const year = today.getFullYear();
  const candidates = [year, year + 1, year - 1].map(
    (candidateYear) => new Date(candidateYear, month, 1),
  );
  const distance = (date: Date) =>
    Math.abs(differenceInCalendarMonths(date, today));
  return candidates.reduce((nearest, candidate) =>
    distance(candidate) < distance(nearest) ? candidate : nearest,
  );
}

/** "in 2 weeks", "3 days ago", "2 weeks from now", "+3d", "-1w" */
function readOffset(text: string, today: Date): Date | null {
  const amountPattern = "(\\d+|a|an|one)";
  const unitPattern = "([a-z]+)";
  const forward =
    new RegExp(`^in ${amountPattern} ?${unitPattern}$`).exec(text) ??
    new RegExp(`^${amountPattern} ?${unitPattern} from (?:now|today)$`).exec(
      text,
    );
  const backward = new RegExp(`^${amountPattern} ?${unitPattern} ago$`).exec(
    text,
  );
  const signed = /^([+-])(\d+) ?([a-z]*)$/.exec(text);

  const read = (amountText: string, unitText: string, sign: 1 | -1) => {
    const unit = unitText === "" ? "day" : UNIT_WORDS[unitText];
    if (!unit) return null;
    const amount = /^\d+$/.test(amountText) ? Number(amountText) : 1;
    return ADD_UNIT[unit](today, sign * amount);
  };

  if (forward) return read(forward[1], forward[2], 1);
  if (backward) return read(backward[1], backward[2], -1);
  if (signed) return read(signed[2], signed[3], signed[1] === "-" ? -1 : 1);
  return null;
}

/** First day of a period: "next week" → the next week's first day, "this month" → the 1st */
function periodStart(
  unit: QueryUnit,
  direction: QueryDirection,
  today: Date,
  weekStartsOn: WeekStartsOn,
): Date {
  const shifted = ADD_UNIT[unit](today, direction);
  if (unit === "week") return startOfWeek(shifted, { weekStartsOn });
  if (unit === "month") return startOfMonth(shifted);
  if (unit === "year") return startOfYear(shifted);
  return shifted;
}

/**
 * A weekday: on its own the next one from today (today when it matches);
 * with a direction, that weekday in the last, this or next week, by
 * `weekStartsOn`
 */
function weekdayDate(
  weekday: number,
  direction: QueryDirection | null,
  today: Date,
  weekStartsOn: WeekStartsOn,
): Date {
  if (direction === null) {
    return addDays(today, (weekday - today.getDay() + 7) % 7);
  }
  const weekStart = startOfWeek(addWeeks(today, direction), { weekStartsOn });
  return addDays(weekStart, (weekday - weekStartsOn + 7) % 7);
}

/**
 * "12/25", "25.12.", "12-25-2027", "2027-12-25": a numeric date in the
 * locale's order (month first in en-US, day first in en-GB), or year first
 * when the first number has four digits
 */
function readNumericDate(
  text: string,
  today: Date,
  locale: Locale,
): Date | null {
  const match = /^(\d{1,4})([/.-])(\d{1,2})(?:\2(\d{1,4}))?\.?$/.exec(text);
  if (!match) return null;
  const [, first, , second, third] = match;

  if (first.length === 4) {
    if (third === undefined) return null;
    return calendarDay(Number(first), Number(second) - 1, Number(third));
  }
  if (first.length > 2 || (third !== undefined && third.length === 3)) {
    return null;
  }

  const pattern = locale.formatLong?.date({ width: "short" }) ?? "MM/dd/yyyy";
  const yearFirst = pattern.search(/y/i) < pattern.search(/d/);
  // Year-first locales ("y/MM/dd") write month before day once the year is gone
  const monthFirst = yearFirst || pattern.indexOf("M") < pattern.indexOf("d");
  const [month, day] = monthFirst
    ? [Number(first) - 1, Number(second)]
    : [Number(second) - 1, Number(first)];

  if (third === undefined) return nextCalendarDay(month, day, today);
  return calendarDay(readYear(third), month, day);
}

/**
 * "dec 25", "25 december", "december 25 2027", "jan", "march 2027": a date
 * with a month name. Without a year it's the next one from today; a month
 * alone is its first day, in the year nearest to today.
 */
function readNamedDate(
  words: string[],
  today: Date,
  locale: Locale,
): Date | null {
  const monthIndex = words.findIndex((word) => readMonth(word, locale) !== -1);
  if (monthIndex === -1 || words.length > 3) return null;
  const month = readMonth(words[monthIndex], locale);
  const numbers = words.filter((_, index) => index !== monthIndex);
  if (!numbers.every((word) => /^\d{1,4}$/.test(word))) return null;

  if (numbers.length === 0) return nearestMonthStart(month, today);

  const [firstNumber, secondNumber] = numbers;
  if (numbers.length === 1) {
    // "december 2027": the month's first day; "december 25": that day
    if (firstNumber.length === 4) {
      return calendarDay(Number(firstNumber), month, 1);
    }
    if (firstNumber.length > 2) return null;
    return nextCalendarDay(month, Number(firstNumber), today);
  }

  // "december 25 2027" or "25 december 2027": the day before the year
  if (firstNumber.length > 2 || secondNumber.length === 3) return null;
  return calendarDay(readYear(secondNumber), month, Number(firstNumber));
}

/**
 * Reads a date typed into Go to date, or returns null when the text isn't
 * one. Accepts, case-insensitively:
 *
 * - "today", "tomorrow", "yesterday"
 * - a weekday: "friday" (the next one, today included), "next friday" (in
 *   next week), "this friday", "last friday"
 * - "next week", "last month", "this year": the period's first day
 * - "in 2 weeks", "in a month", "3 days ago", "2 weeks from now", "+3d"
 * - a month name with a day and year in either order: "dec 25",
 *   "25 december", "December 25th, 2027", "sept 5"; a month alone ("jan")
 *   or with a year ("march 2027") is its first day
 * - a numeric date in the locale's order: "12/25" and "12/25/2027" in
 *   en-US, "25/12" in en-GB, "25.12." in German, and "2027-12-25" anywhere
 * - a day of the month ("25", "25th": the next one), or a year ("2027")
 *
 * A leading weekday is skipped ("Fri Dec 25"). Month and weekday names come
 * from the locale and from English. A date without a year is the next one
 * from today, today included, as in Notion Calendar ("oct 30" typed in
 * November is next year's). The result is the day's midnight.
 */
export function parseDateQuery(
  text: string,
  { today: todayInput, locale = enUS, weekStartsOn }: DateQueryOptions,
): Date | null {
  const today = startOfDay(todayInput);
  const weekStart = weekStartsOn ?? locale.options?.weekStartsOn ?? 0;
  const normalized = normalizeName(text.trim())
    .replace(/,/g, " ")
    .replace(/(\d)(?:st|nd|rd|th)\b/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
  if (normalized.length === 0) return null;

  if (normalized in DAY_WORDS) return addDays(today, DAY_WORDS[normalized]);

  const offset = readOffset(normalized, today);
  if (offset) return startOfDay(offset);

  const words = normalized
    .split(" ")
    .map((word) => word.replace(/\.$/, ""))
    .filter((word) => word.length > 0 && !FILLER_WORDS.has(word));
  if (words.length === 0) return null;

  // "next week", "this month", "next friday", "last fri"
  if (words.length === 2 && words[0] in DIRECTION_WORDS) {
    const direction = DIRECTION_WORDS[words[0]];
    const unit = UNIT_WORDS[words[1]];
    if (unit && words[1].length > 1) {
      return periodStart(unit, direction, today, weekStart);
    }
    const weekday = readWeekday(words[1], locale);
    if (weekday !== -1) {
      return weekdayDate(weekday, direction, today, weekStart);
    }
    return null;
  }

  // A weekday alone, or one before a date: "friday", "Fri Dec 25"
  if (
    readWeekday(words[0], locale) !== -1 &&
    readMonth(words[0], locale) === -1
  ) {
    if (words.length === 1) {
      return weekdayDate(readWeekday(words[0], locale), null, today, weekStart);
    }
    words.shift();
  }

  if (words.length === 1) {
    const [word] = words;
    const numeric = readNumericDate(word, today, locale);
    if (numeric) return numeric;
    if (/^\d{4}$/.test(word)) return calendarDay(Number(word), 0, 1);
    if (/^\d{1,2}$/.test(word)) {
      return nextDayOfMonth(Number(word), today);
    }
  }

  return readNamedDate(words, today, locale);
}

/**
 * The day Go to date shows for typed text: "Friday, December 25", with the
 * year when it isn't today's ("Saturday, December 25, 2027"), in the
 * locale's words and order
 */
export function formatDateQueryResult(
  date: Date,
  today: Date,
  locale: Locale = enUS,
): string {
  return new Intl.DateTimeFormat(locale.code, {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: date.getFullYear() === today.getFullYear() ? undefined : "numeric",
  }).format(date);
}
